"""Writes src/generated/HtmlEntityData.sa: the named character references
of HTML ("&amp;", "&copy;", ...), the WHATWG table as Python's
html.entities.html5 holds it.

Run from compiler/:  python src/tools/gen_html_entities.py
"""
import html.entities

OUT = "src/generated/HtmlEntityData.sa"


def c_bytes(text):
    """A C string literal of `text` in UTF-8, every byte escaped."""
    return '"' + "".join("\\x%02X" % b for b in text.encode("utf-8")) + '"'


def main():
    table = html.entities.html5
    names = sorted(table)
    out = [
        "// quantum: cpp",
        "// Generated by src/tools/gen_html_entities.py from the WHATWG table of named",
        "// character references (Python's html.entities.html5). Do not edit.",
        '#include "../html/HtmlEntities.h.sa"',
        "",
        "namespace html",
        "{",
        "",
        "const int kEntityCount = %d;" % len(names),
        "",
        "const char *const kEntities[] = {",
    ]
    for name in names:
        out.append('    "%s", %s,' % (name, c_bytes(table[name])))
    out += ["};", "", "} // namespace html", ""]
    with open(OUT, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(out))
    print("wrote %s: %d references" % (OUT, len(names)))


if __name__ == "__main__":
    main()
